const ozGeography1Orta = <(String, String, List<String>, String)>[
  ('Türkiye\'nin kuzey yarım kürede ve orta kuşakta bulunmasının doğrudan bir sonucu aşağıdakilerden hangisidir?', 'Dört mevsimin belirgin biçimde yaşanması', ['Ülkenin üç tarafının denizlerle çevrili olması', 'Kıyı ile iç kesim arasında yükselti farkının büyük olması', 'Akarsuların kısa ve hızlı akması'], 'Orta kuşakta yer almak güneş ışınlarının geliş açısının yıl içinde değişmesine, böylece mevsimlerin belirgin yaşanmasına yol açar.'),
  ('Türkiye\'de güneye bakan yamaçların kuzey yamaçlara göre daha fazla güneş alması hangi konum özelliğinin sonucudur?', 'Ülkenin Yengeç Dönencesi\'nin kuzeyinde yer alması', ['Ülkenin 26°-45° doğu boylamları arasında bulunması', 'Ülkenin Alp-Himalaya kıvrım kuşağında olması', 'Ülkenin ortalama yükseltisinin fazla olması'], 'Yengeç Dönencesi\'nin kuzeyindeki yerlerde güneş öğle vakti daima güney yönündedir; bu yüzden güneye bakan yamaçlar daha çok ışık ve ısı alır.'),
  ('Sinop ile Hatay karşılaştırıldığında yıl içinde gece ile gündüz süreleri arasındaki farkın Sinop\'ta daha büyük olmasının nedeni nedir?', 'Sinop\'un Ekvator\'a daha uzak olması', ['Sinop\'un daha doğuda bulunması', 'Sinop\'un daha yüksek olması', 'Sinop\'un Karadeniz\'e kıyısı olması'], 'Ekvator\'dan kutuplara gidildikçe gece-gündüz süreleri arasındaki fark artar. Sinop, Hatay\'dan daha kuzeydedir.'),
  ('Türkiye\'nin en batı ucu olarak kabul edilen nokta hangi adadadır?', 'Gökçeada', ['Bozcaada', 'İmralı Adası', 'Marmara Adası'], 'Türkiye\'nin en batı ucu Çanakkale\'ye bağlı Gökçeada\'daki Avlaka Burnu\'dur.'),
  ('Hatay\'ın güneyindeki Beysun Köyü hangi özelliğiyle bilinir?', 'Türkiye\'nin en güney noktası olmasıyla', ['Türkiye\'nin en alçak noktası olmasıyla', 'Türkiye\'nin en doğu noktası olmasıyla', 'Türkiye\'nin en sıcak meteoroloji istasyonu olmasıyla'], 'Türkiye\'nin güney ucu yaklaşık 36° kuzey paralelinde, Hatay\'daki Beysun Köyü yakınındadır.'),
  ('Türkiye\'de hiçbir yerde güneş ışınlarının yıl içinde 90° açıyla gelmemesinin nedeni nedir?', 'Ülkenin dönenceler arasında bulunmaması', ['Ülkenin Ekvator\'a çok yakın olması', 'Ülkenin yükseltisinin fazla olması', 'Ülkenin doğu yarım kürede bulunması'], 'Güneş ışınları yalnız iki dönence arasındaki yerlere yılda en az bir kez dik gelir. Türkiye 23°27\' kuzey paralelinin kuzeyindedir.'),
  ('Türkiye\'deki taşkömürü yataklarının oluştuğu jeolojik zaman hangisidir?', 'Paleozoik (I. zaman)', ['Mesozoik (II. zaman)', 'Senozoik Tersiyer dönemi', 'Kuaterner (IV. zaman)'], 'Zonguldak çevresindeki taşkömürü, Paleozoik\'in Karbonifer devrinde bataklık ormanlarının kömürleşmesiyle oluşmuştur.'),
  ('İstanbul ve Çanakkale boğazlarının bugünkü görünümünü kazandığı jeolojik dönem hangisidir?', 'Kuaterner', ['Paleozoik', 'Mesozoik', 'Tersiyer\'in başları'], 'Boğazlar, akarsu vadilerinin Kuaterner\'de buzul arası dönemlerde yükselen deniz sularıyla dolmasıyla oluşmuştur.'),
  ('Türkiye\'deki linyit yataklarının büyük kısmı hangi jeolojik zamanda oluşmuştur?', 'Tersiyer', ['Paleozoik', 'Mesozoik', 'Prekambriyen'], 'Linyitler, Tersiyer\'deki göl ve bataklık ortamlarında biriken bitki kalıntılarının kömürleşmesiyle oluşmuştur.'),
  ('Istranca, Menteşe ve Kırşehir masiflerinin ortak özelliği aşağıdakilerden hangisidir?', 'Türkiye\'nin en eski arazilerinden olmaları', ['Kuaterner\'de volkanizmayla oluşmaları', 'Tamamen kalker tortullardan oluşmaları', 'Tersiyer\'de denizden yükselmiş genç araziler olmaları'], 'Bu masifler Paleozoik ve daha eski kayaçlardan oluşan, aşınmış sert çekirdek alanlardır.'),
  ('Doğu Anadolu Fay Hattı genel olarak hangi doğrultuda uzanır?', 'Kuzeydoğu-güneybatı', ['Doğu-batı', 'Kuzey-güney', 'Kuzeybatı-güneydoğu'], 'Doğu Anadolu Fayı Karlıova\'dan güneybatıya, Kahramanmaraş üzerinden Hatay\'a doğru uzanır.'),
  ('Arap levhasının kuzeye doğru hareketi Anadolu levhasını hangi yöne itmektedir?', 'Batıya', ['Kuzeye', 'Doğuya', 'Güneydoğuya'], 'Kuzeyden Avrasya, doğu-güneydoğudan Arap levhasının sıkıştırmasıyla Anadolu levhası KAF ve DAF boyunca batıya doğru kaçar.'),
  ('Bozdağlar ile Aydın Dağları\'nın oluşum bakımından ortak özelliği aşağıdakilerden hangisidir?', 'Kırılma sonucu yükselmiş horstlar olmaları', ['Volkanik koni olmaları', 'Tortul katmanların kıvrılmasıyla oluşmaları', 'Buzul birikinti dağları olmaları'], 'Ege\'deki bu dağlar fay hatları boyunca yükselmiş bloklardır; aralarındaki grabenlerde Gediz ve Büyük Menderes akar.'),
  ('Kuzey Anadolu Fay Hattı batıda hangi körfez aracılığıyla Ege Denizi\'ne uzanır?', 'Saros Körfezi', ['Edremit Körfezi', 'İzmir Körfezi', 'Gökova Körfezi'], 'KAF, Marmara Denizi\'ni geçip Gelibolu Yarımadası\'nın kuzeyinden Saros Körfezi\'ne ulaşır.'),
  ('Kıvrılma ile kırılma arasındaki temel fark hangisinde doğru verilmiştir?', 'Kıvrılma esnek tabakalarda, kırılma sert ve esnekliğini yitirmiş tabakalarda görülür.', ['Kıvrılma yalnız volkanik kayaçlarda, kırılma yalnız tortul kayaçlarda görülür.', 'Kıvrılma dış kuvvetlerle, kırılma iç kuvvetlerle gerçekleşir.', 'Kıvrılma çukur alanlar, kırılma her zaman yüksek alanlar oluşturur.'], 'Her ikisi de iç kuvvetlerle olur; yan basınç tortul ve esnek katmanları kıvırır, sert katmanlarda ise kırılmalar meydana gelir.'),
  ('Kuzey Anadolu Dağları\'nın kıyıya paralel uzanmasının Karadeniz kıyılarındaki doğal bir sonucu hangisidir?', 'Kıyıdan iç kesime ulaşımın sınırlı vadilerle sağlanması', ['Kıyılarda ria tipi girintili yapının oluşması', 'Kıyı ovalarının geniş olması', 'Akarsuların uzun ve yavaş akması'], 'Kıyıya paralel dağlar kıyı ile iç kesimi birbirinden ayırır; geçişler ancak vadiler ve geçitlerle mümkündür.'),
  ('Batıdan doğuya doğru sıralandığında hangisi Kuzey Anadolu Dağları\'nın doğru dizilişidir?', 'Köroğlu - Ilgaz - Canik - Kaçkar', ['Ilgaz - Köroğlu - Kaçkar - Canik', 'Canik - Ilgaz - Köroğlu - Kaçkar', 'Kaçkar - Canik - Ilgaz - Köroğlu'], 'Köroğlu Bolu çevresinde, Ilgaz Kastamonu-Çankırı arasında, Canik Samsun-Ordu çevresinde, Kaçkar ise Rize-Artvin\'dedir.'),
  ('Kuzey Anadolu Dağları\'nın kuzey yamaçları ile güney yamaçları arasında bitki örtüsü bakımından belirgin fark görülmesinin temel nedeni nedir?', 'Kuzey yamaçların nemli hava kütlelerinden daha çok yağış alması', ['Güney yamaçların denize daha yakın olması', 'Kuzey yamaçların daha çok güneş ışığı alması', 'Güney yamaçlarda toprağın daha derin olması'], 'Denizden gelen nemli hava kuzey yamaçlarda yükselerek bol yağış bırakır; güney yamaçlar yağış gölgesinde kalır.'),
  ('Toros Dağları\'nın orta bölümünde yer alan ve en yüksek noktası Demirkazık olan dağ kütlesi hangisidir?', 'Aladağlar', ['Bolkar Dağları', 'Beydağları', 'Sultan Dağları'], 'Niğde-Kayseri-Adana arasındaki Aladağlar\'ın en yüksek zirvesi Demirkazık\'tır ve dağcılıkta önemlidir.'),
  ('Çukurova ile İç Anadolu arasında Toroslar\'ı aşan tarihî geçit hangisidir?', 'Gülek Boğazı', ['Belen Geçidi', 'Sertavul Geçidi', 'Kopdağı Geçidi'], 'Gülek Boğazı Tarsus ile Pozantı arasında Toroslar\'ı aşar; tarih boyunca Anadolu\'dan Çukurova\'ya ana yol olmuştur.'),
  ('Hatay\'da İskenderun ile Antakya arasında yer alan ve Belen Geçidi ile aşılan dağ hangisidir?', 'Amanos (Nur) Dağları', ['Bolkar Dağları', 'Aladağlar', 'Binboğa Dağları'], 'Amanos Dağları İskenderun Körfezi\'nin doğusunda kuzey-güney doğrultusunda uzanır; Belen Geçidi buradadır.'),
  ('Kapadokya\'daki tüf katmanlarını oluşturan volkanik malzemenin başlıca kaynağı aşağıdaki dağlardan hangileridir?', 'Erciyes, Hasan ve Melendiz', ['Ağrı, Tendürek ve Süphan', 'Kula, Karacadağ ve Nemrut', 'Uludağ, Kazdağı ve Spil'], 'Bu volkanlardan çıkan küller birikip tüfleşmiş; aşınmayla peribacaları ortaya çıkmıştır.'),
  ('Manisa\'da bulunan, Türkiye\'nin en genç volkanik konilerinden bazılarını barındıran ve jeopark olarak tanınan alan hangisidir?', 'Kula volkanları', ['Karapınar volkanları', 'Nemrut kalderası', 'Tendürek lavları'], 'Kula çevresindeki koniler ve lav akıntıları Kuaterner\'de oluşmuştur; bölge UNESCO Küresel Jeoparkı\'dır.'),
  ('Diyarbakır ile Şanlıurfa arasında yer alan, geniş tabanlı ve yayvan biçimli volkanik dağ hangisidir?', 'Karacadağ', ['Nemrut Dağı', 'Hasan Dağı', 'Süphan Dağı'], 'Güneydoğu Anadolu\'daki Karacadağ akışkan bazaltik lavlarla oluşmuş kalkan tipi bir volkandır.'),
  ('Kuzey Anadolu Dağları ile Toroslar\'ın genel uzanışlarının ortak sonucu aşağıdakilerden hangisidir?', 'İç Anadolu\'nun yağış gölgesinde kalarak kurak olması', ['Kıyılarda geniş ovaların bulunması', 'Türkiye\'de akarsuların hep kuzeye akması', 'İç kesimlerde kışların ılık geçmesi'], 'Kuzeyde ve güneyde kıyıya paralel dağlar nemli hava kütlelerinin iç kesimlere ulaşmasını engeller, İç Anadolu yağış gölgesinde kalır.'),
  ('Göksu Nehri\'nin Akdeniz\'e döküldüğü yerde oluşan delta ovası hangisidir?', 'Silifke Ovası', ['Antalya Ovası', 'Mersin Ovası', 'Dalaman Ovası'], 'Göksu, Orta Toroslar\'dan inerek Silifke yakınında deltasını oluşturur; delta ayrıca önemli bir sulak alandır.'),
  ('Elmalı ve Muğla ovalarının oluşumu bakımından ortak özelliği nedir?', 'Karstik polye olmaları', ['Delta ovası olmaları', 'Volkanik set ovaları olmaları', 'Buzul birikim ovası olmaları'], 'Bu ovalar kalkerin geniş alanda çözünmesiyle oluşan, tabanı alüvyonla örtülü karstik çukurluklardır.'),
  ('Erzincan, Muş ve Iğdır ovalarının ortak oluşum kökeni nedir?', 'Tektonik çöküntü', ['Delta birikimi', 'Karstik çözünme', 'Rüzgâr birikimi'], 'Doğu Anadolu\'daki bu ovalar fay hatları boyunca çöken alanların akarsu alüvyonlarıyla dolmasıyla oluşmuştur.'),
  ('Kıyıdaki bir delta ovasında taban suyunun yüzeye yakın olmasının olası bir sonucu aşağıdakilerden hangisidir?', 'Bataklık ve sulak alanların oluşması', ['Toprağın kireçli ve kurak olması', 'Tarım alanlarının taşlık olması', 'Akarsu yatağının derinleşmesi'], 'Delta düzlükleri deniz seviyesine yakın ve eğimsizdir; drenajın zayıf olması bataklık ve lagün oluşumunu kolaylaştırır.'),
  ('Ardahan ile Erzurum-Kars yöresindeki platoların oluşumu hangi süreçle ilgilidir?', 'Akışkan lavların geniş alanları örtmesi', ['Akarsuların derin vadiler açması', 'Kalkerin çözünmesi', 'Buzul birikintilerinin yığılması'], 'Doğu Anadolu\'nun kuzeydoğusundaki geniş düzlükler bazaltik lav örtüleriyle oluşmuş lav platolarıdır.'),
  ('Konya\'daki Obruk Platosu adını aşağıdaki yer şekillerinden hangisinden alır?', 'Kalkerin çözünmesiyle oluşan derin çökme çukurları', ['Rüzgârın oyduğu tafoni yuvaları', 'Volkan patlamalarının bıraktığı kraterler', 'Buzulun oyduğu sirk çanakları'], 'Obruklar, yeraltındaki boşlukların tavanının çökmesiyle oluşan dik kenarlı karstik çukurlardır.'),
  ('Karstik şekiller küçükten büyüğe sıralandığında doğru sıra hangisidir?', 'Lapya - Dolin - Uvala - Polye', ['Dolin - Lapya - Polye - Uvala', 'Uvala - Polye - Lapya - Dolin', 'Polye - Uvala - Dolin - Lapya'], 'Çözünme ilerledikçe oluklar (lapya) çukurlara (dolin), çukurlar birleşerek uvalaya ve sonunda polyeye dönüşür.'),
  ('Türkiye\'de karstik şekillerin en yaygın görüldüğü bölüm aşağıdakilerden hangisidir?', 'Batı ve Orta Toroslar', ['Doğu Karadeniz kıyısı', 'Ergene Havzası', 'Erzurum-Kars Bölümü'], 'Toroslar\'ın Mesozoik kalkerlerden oluşan kesimleri, özellikle Teke ve Taşeli yöreleri, karst bakımından en zengin alanlardır.'),
  ('Türkiye\'de fiyort tipi kıyının bulunmamasının nedeni aşağıdakilerden hangisidir?', 'Kıyılarının buzul dönemlerinde buzullarla örtülmemiş olması', ['Kıyılarının tamamen kumsallardan oluşması', 'Denizlerinin tuzluluğunun yüksek olması', 'Kıyılarda akarsuların olmaması'], 'Fiyortlar buzul vadilerinin sular altında kalmasıyla oluşur; Türkiye kıyıları Kuaterner buzullaşmasında buzulla kaplanmamıştır.'),
  ('Enine kıyıların boyuna kıyılara göre daha fazla doğal liman barındırmasının nedeni nedir?', 'Körfez ve koyların korunaklı su alanları oluşturması', ['Kıyıların daha derin bir kıta sahanlığına sahip olması', 'Bu kıyıların daha fazla yağış alması', 'Enine kıyılarda akarsuların daha uzun olması'], 'Girintili kıyılarda körfez ve koylar dalgalara karşı korunaklıdır; bu da doğal liman oluşumuna elverişlidir.'),
  ('Kapıdağ Yarımadası ile Sinop\'taki Boztepe\'nin ortak oluşum özelliği nedir?', 'Eskiden ada olup tombolo ile karaya bağlanmaları', ['Volkanik patlamayla oluşmaları', 'Akarsu deltasıyla genişlemeleri', 'Kıyı okuyla denizden ayrılmaları'], 'Her ikisi de kıyı akıntılarının biriktirdiği malzemeyle karaya eklenmiş eski adalardır.'),
  ('Kıyı akıntılarının biriktirdiği malzemenin kıyıdan denize doğru dil şeklinde uzanmasıyla oluşan yer şekli hangisidir?', 'Kıyı oku', ['Falez', 'Abrazyon platformu', 'Tombolo'], 'Kıyı oku bir ucu karaya bağlı, diğer ucu denize uzanan kum ve çakıl setidir.'),
  ('İstanbul Boğazı\'nda yüzey akıntısının Karadeniz\'den Marmara\'ya doğru olmasının temel nedeni nedir?', 'Karadeniz\'in daha az tuzlu ve su seviyesinin daha yüksek olması', ['Marmara Denizi\'nin daha soğuk olması', 'Karadeniz\'e akarsu dökülmemesi', 'Boğazın kuzeyden güneye eğimli olması'], 'Karadeniz\'e bol akarsu döküldüğünden tuzluluğu düşük ve seviyesi yüksektir; az yoğun su üstten Marmara\'ya akar.'),
  ('İstanbul Boğazı\'nın dip akıntısı hangi yöne doğrudur?', 'Marmara\'dan Karadeniz\'e', ['Karadeniz\'den Marmara\'ya', 'Marmara\'dan Ege\'ye', 'Akdeniz\'den Marmara\'ya'], 'Daha tuzlu ve yoğun olan Marmara suyu dipten Karadeniz\'e doğru akar.'),
  ('Çanakkale ve İstanbul boğazlarının oluşumunu en iyi açıklayan ifade hangisidir?', 'Eski akarsu vadilerinin deniz sularıyla dolması', ['Volkanik patlamaların açtığı yarıklar', 'Buzulların oyduğu vadiler', 'Rüzgâr aşındırmasıyla açılan geçitler'], 'Boğazlar Kuaterner\'de deniz seviyesinin yükselmesiyle sular altında kalan akarsu vadileridir.'),
  ('Marmara Denizi\'nin tuzluluğu Karadeniz ile Ege Denizi\'ne göre nasıldır?', 'Karadeniz\'den yüksek, Ege\'den düşük', ['Her iki denizden de düşük', 'Her iki denizden de yüksek', 'Karadeniz\'den düşük, Ege\'den yüksek'], 'Marmara az tuzlu Karadeniz suyu ile tuzlu Akdeniz suyunun karıştığı bir iç denizdir; tuzluluğu ikisinin arasındadır.'),
  ('Asya kıtasının en batı ucu olarak bilinen Baba Burnu hangi yarımadadadır?', 'Biga Yarımadası', ['Gelibolu Yarımadası', 'Kocaeli Yarımadası', 'Karaburun Yarımadası'], 'Baba Burnu Çanakkale\'nin Ayvacık ilçesinde, Biga Yarımadası\'nın güneybatı ucundadır.'),
  ('Muğla\'da Gökova Körfezi ile Hisarönü Körfezi arasında uzanan dar ve uzun yarımada hangisidir?', 'Datça (Reşadiye) Yarımadası', ['Bodrum Yarımadası', 'Teke Yarımadası', 'Çeşme Yarımadası'], 'Datça Yarımadası Ege ile Akdeniz\'in birleştiği yerde, güneybatı Anadolu\'da denize doğru uzanır.'),
  ('Gelibolu Yarımadası\'nı kuzeybatıdan sınırlayan körfez hangisidir?', 'Saros Körfezi', ['Edremit Körfezi', 'Gemlik Körfezi', 'Kuşadası Körfezi'], 'Saros Körfezi Gelibolu Yarımadası\'nın kuzeybatısında Ege Denizi\'ne açılır.'),
  ('Aşağıdaki akarsulardan hangisi sularını kapalı bir havzaya ulaştırır?', 'Aras', ['Sakarya', 'Gediz', 'Seyhan'], 'Aras, sularını Kura ile birleştikten sonra denizlerle bağlantısı olmayan Hazar\'a ulaştırır.'),
  ('Kapalı havzalardaki göllerin genellikle tuzlu ya da sodalı olmasının nedeni nedir?', 'Gelen suyun dışarı akmayıp buharlaşması', ['Göllerin deniz suyuyla beslenmesi', 'Bu bölgelerde yağışın çok fazla olması', 'Göllerin buzul eriyikleriyle dolması'], 'Akarsuların getirdiği çözünmüş tuzlar gölde kalır; su buharlaştıkça tuz yoğunlaşır.'),
  ('Kızılırmak\'ın İç Anadolu\'da geniş bir yay çizerek akmasının nedeni aşağıdakilerden hangisidir?', 'Yer şekillerinin akış yönünü değiştirmesi', ['Akarsuyun buzullarla beslenmesi', 'Akarsuyun kapalı havzaya akması', 'Yatağının tümüyle volkanik olması'], 'Kızılırmak doğuda batıya akarken dağ ve platoların engeliyle güneybatıya, sonra kuzeye dönerek yay çizer.'),
  ('Hirfanlı, Kesikköprü ve Altınkaya barajları hangi akarsu üzerindedir?', 'Kızılırmak', ['Sakarya', 'Yeşilırmak', 'Seyhan'], 'Bu barajlar Kızılırmak\'ın orta ve aşağı çığırında kuruludur.'),
  ('Fırat Nehri\'ni oluşturan iki ana kol hangileridir?', 'Karasu ve Murat', ['Batman ve Garzan', 'Kelkit ve Tozanlı', 'Zamantı ve Göksu'], 'Erzurum\'dan gelen Karasu ile Ağrı\'dan gelen Murat Keban Barajı çevresinde birleşerek Fırat\'ı oluşturur.'),
  ('Dicle Nehri\'nin kaynağını aldığı göl hangisidir?', 'Hazar Gölü', ['Van Gölü', 'Çıldır Gölü', 'Eğirdir Gölü'], 'Dicle, Elazığ\'daki Hazar Gölü çevresinden doğar.'),
  ('Batman ve Garzan çayları hangi akarsuyun kollarıdır?', 'Dicle', ['Fırat', 'Aras', 'Seyhan'], 'Batman ve Garzan çayları Güneydoğu Toroslar\'dan inerek Dicle\'ye katılır.'),
  ('Fırat ve Dicle\'nin akım miktarının ilkbaharda en yüksek düzeye çıkmasının ana nedeni nedir?', 'Doğu Anadolu\'daki kar örtüsünün erimesi', ['Güneydoğu\'da yaz yağışlarının bol olması', 'Akdeniz\'den gelen sıcak hava akımları', 'Barajların yazın su bırakması'], 'Kaynak alanlarındaki yüksek dağlarda kış boyunca biriken kar ilkbaharda eriyerek akımı artırır.'),
  ('Fırat ile Dicle\'nin Türkiye dışında birleşerek oluşturduğu su yolu hangisidir?', 'Şattülarap', ['Habur', 'Asi', 'Ürdün'], 'İki nehir Irak\'ta birleşerek Şattülarap\'ı oluşturur ve Basra Körfezi\'ne dökülür.'),
  ('Porsuk Çayı ve Ankara Çayı hangi akarsuyun kollarıdır?', 'Sakarya', ['Kızılırmak', 'Yeşilırmak', 'Susurluk'], 'Eskişehir\'den gelen Porsuk ve Ankara\'dan gelen Ankara Çayı, İç Anadolu\'nun batısında Sakarya\'ya katılır.'),
  ('Sarıyar ve Gökçekaya barajları hangi akarsu üzerinde kurulmuştur?', 'Sakarya', ['Fırat', 'Kızılırmak', 'Gediz'], 'Sarıyar ve Gökçekaya Sakarya Nehri\'nin orta çığırında, Ankara-Eskişehir sınırı çevresindedir.'),
  ('Kelkit ve Çekerek çaylarını alan, Amasya ve Tokat\'tan geçen akarsu hangisidir?', 'Yeşilırmak', ['Kızılırmak', 'Sakarya', 'Çoruh'], 'Kelkit Çayı Erbaa yakınında, Çekerek ise Amasya çevresinde Yeşilırmak\'a katılır.'),
  ('Aslantaş ve Menzelet barajları hangi akarsu üzerindedir?', 'Ceyhan', ['Seyhan', 'Göksu', 'Asi'], 'Kahramanmaraş Elbistan çevresinden doğan Ceyhan üzerinde Menzelet, Sır ve Aslantaş barajları bulunur.'),
  ('Kuzeye doğru akması nedeniyle Türkiye akarsuları arasında dikkat çeken ve Hatay\'da Akdeniz\'e dökülen nehir hangisidir?', 'Asi', ['Ceyhan', 'Göksu', 'Aksu'], 'Asi Lübnan\'dan doğar, Suriye\'den kuzeye akarak Hatay\'a girer ve Samandağ yakınında Akdeniz\'e dökülür.'),
  ('Afyonkarahisar\'ın Dinar ilçesinden doğup Söke Ovası\'ndan geçerek Ege\'ye dökülen akarsu hangisidir?', 'Büyük Menderes', ['Küçük Menderes', 'Gediz', 'Bakırçay'], 'Büyük Menderes Dinar\'dan doğar, Denizli ve Aydın\'dan geçerek Söke yakınında denize ulaşır.'),
  ('Antik Efes ve Milet kentlerinin bugün denizden uzakta kalmasının temel nedeni nedir?', 'Akarsuların taşıdığı alüvyonla kıyının ilerlemesi', ['Deniz seviyesinin yüz metre düşmesi', 'Bölgenin volkanik etkinlikle yükselmesi', 'Kentlerin depremden sonra iç kesime taşınması'], 'Küçük ve Büyük Menderes\'in getirdiği alüvyonlar körfezleri doldurmuş, kıyı çizgisi denize doğru kilometrelerce ilerlemiştir.'),
  ('Manisa Ovası\'ndan geçen ve İzmir Körfezi\'nin kuzeyinde Ege\'ye dökülen akarsu hangisidir?', 'Gediz', ['Bakırçay', 'Küçük Menderes', 'Simav Çayı'], 'Gediz Murat Dağı\'ndan doğar, Manisa\'dan geçerek Foça yakınında Ege Denizi\'ne dökülür.'),
  ('Trakya\'nın iç kesimindeki ovayı sulayan ve Meriç\'e karışan akarsu hangisidir?', 'Ergene', ['Susurluk', 'Biga Çayı', 'Nilüfer'], 'Ergene, Istranca Dağları\'nın güney eteklerinden gelen derelerle beslenir ve Meriç\'e katılır.'),
  ('Ege Bölgesi\'ndeki akarsuların genellikle doğu-batı doğrultusunda akmasının nedeni nedir?', 'Akarsuların horstlar arasındaki grabenleri izlemesi', ['Kıyıya paralel sıradağların bulunması', 'Bölgenin kapalı havza olması', 'Rüzgârların akarsuları batıya yönlendirmesi'], 'Ege\'deki çöküntü ovaları doğu-batı uzanışlıdır; akarsular bu oluklar boyunca denize akar.'),
  ('Deriner, Yusufeli ve Borçka barajları hangi akarsu üzerindedir?', 'Çoruh', ['Kelkit', 'Aras', 'Fırat\'ın Karasu kolu'], 'Çoruh\'un derin ve dar vadisi, yüksek baraj gövdelerinin kurulmasına uygun olduğundan art arda büyük barajlar inşa edilmiştir.'),
  ('Ardahan\'dan doğup sularını Gürcistan ve Azerbaycan üzerinden Hazar Denizi\'ne ulaştıran akarsu hangisidir?', 'Kura', ['Çoruh', 'Aras', 'Murat'], 'Kura Ardahan yöresinden doğar ve Azerbaycan\'da Aras ile birleşerek Hazar\'a dökülür.'),
  ('Iğdır Ovası\'nı sulayan ve bir kesiminde Türkiye ile Ermenistan arasında sınır oluşturan akarsu hangisidir?', 'Aras', ['Kura', 'Murat', 'Zap Suyu'], 'Aras Kağızman\'dan sonra Iğdır Ovası\'nın kuzeyinden akarak sınır boyunca ilerler.'),
  ('Doğu Karadeniz\'deki derelerin hidroelektrik üretimine elverişli olmasının iki temel nedeni hangisinde birlikte verilmiştir?', 'Bol yağış ve yüksek eğim', ['Geniş delta ve az yağış', 'Karstik kaynaklar ve geniş ovalar', 'Uzun yatak ve düşük eğim'], 'Her mevsim yağış alan bölgede kısa mesafede büyük yükselti farkı bulunur; bu, suyun düşü enerjisini artırır.'),
  ('Rize\'de akan, vadisi doğal güzelliği ve rafting etkinlikleriyle bilinen dere hangisidir?', 'Fırtına Deresi', ['Değirmendere', 'Melen Çayı', 'Filyos Çayı'], 'Fırtına Deresi Kaçkar Dağları\'ndan inerek Ardeşen çevresinde Karadeniz\'e dökülür.'),
  ('Zonguldak ile Karabük arasında akan ve Batı Karadeniz\'in önemli akarsularından olan çay hangisidir?', 'Filyos (Yenice) Çayı', ['Harşit Çayı', 'Fırtına Deresi', 'Gönen Çayı'], 'Filyos Çayı Batı Karadeniz\'de Karabük ve Zonguldak\'tan geçerek Karadeniz\'e dökülür.'),
  ('Bir akarsuyun havzasında ormanların tahrip edilmesi akarsu rejimini nasıl etkiler?', 'Taşkınların sıklaşmasına ve rejimin düzensizleşmesine yol açar.', ['Akımı yıl boyunca dengeli hâle getirir.', 'Akarsuyun taşıdığı alüvyon miktarını azaltır.', 'Yeraltı suyuna sızmayı artırarak debiyi sabitler.'], 'Bitki örtüsü yağış suyunu tutar ve toprağa sızdırır; ormanlar yok olunca yüzey akışı hızlanır, taşkınlar artar.'),
  ('Bir akarsu üzerine baraj yapılmasının barajın aşağısındaki akış üzerindeki etkisi genellikle nedir?', 'Akımın yıl içinde daha dengeli hâle gelmesi', ['Akarsuyun taşıdığı alüvyonun artması', 'Akarsuyun kurumaya başlaması', 'Akarsuyun yönünün değişmesi'], 'Baraj gölü bol sulu dönemde suyu biriktirir ve kurak dönemde bırakır; böylece akım düzenlenir.'),
  ('Türkiye akarsularının genel olarak düzensiz rejimli olmasının en önemli nedeni aşağıdakilerden hangisidir?', 'Yağışın yıl içinde mevsimlere dengesiz dağılması', ['Akarsuların tamamının buzullarla beslenmesi', 'Akarsu havzalarının çok küçük olması', 'Akarsuların yalnız yeraltı sularıyla beslenmesi'], 'Karadeniz dışında yağışın kışa ve ilkbahara yoğunlaşması, yazın akımın çok düşmesine yol açar.'),
  ('Akarsu yataklarının eğimli olması ve şelale gibi kırıklar içermesi Türkiye akarsularının hangi özelliğini kısıtlar?', 'Ulaşıma elverişliliğini', ['Enerji potansiyelini', 'Sulamada kullanımını', 'Balıkçılığa uygunluğunu'], 'Ortalama yükseltinin fazla olması akarsuları eğimli ve hızlı yapar; bu da gemi ulaşımını büyük ölçüde engeller.'),
  ('Bursa\'da yer alan Uluabat ve Manyas (Kuş) göllerinin ortak oluşum türü nedir?', 'Tektonik', ['Volkanik', 'Heyelan seti', 'Buzul aşındırması'], 'Güney Marmara\'daki bu göller kırılmalarla oluşan çöküntü alanlarında birikmiş sulardır.'),
  ('Elazığ\'da bulunan ve Doğu Anadolu Fay Hattı üzerinde oluşmuş tektonik göl hangisidir?', 'Hazar Gölü', ['Çıldır Gölü', 'Nazik Gölü', 'Haçlı Gölü'], 'Hazar Gölü DAF\'ın oluşturduğu çöküntüde yer alır ve Dicle\'nin kaynak alanındadır.'),
  ('Tektonik göllerin genellikle uzun ve dar bir biçime sahip olmasının nedeni nedir?', 'Fay hatları boyunca uzanan çöküntü alanlarında oluşmaları', ['Lavların vadiyi enine kesmesi', 'Kalkerin dairesel biçimde çözünmesi', 'Dalgaların kıyıda kum biriktirmesi'], 'Fay hatları çizgisel olduğundan boyunca çöken alanlar da uzun ve dar olur; göller bu çanakların biçimini alır.'),
  ('Ardahan\'da yer alan ve lav akıntılarının bir çukurun önünü kapatmasıyla oluşan göl hangisidir?', 'Çıldır Gölü', ['Tortum Gölü', 'Hazar Gölü', 'Sera Gölü'], 'Çıldır Gölü volkanik set gölüdür; kışın yüzeyi donar ve üzerinde balık avlanır.'),
  ('Bolu\'daki Yedigöller ile Trabzon\'daki Sera Gölü\'nün ortak oluşum türü nedir?', 'Heyelan set gölü', ['Krater gölü', 'Buzul gölü', 'Kıyı set gölü'], 'Her iki göl de yamaçtan kayan kütlelerin vadilerin önünü kapatmasıyla oluşmuştur.'),
  ('Burdur\'da bulunan, beyaz kumsalları ve turkuaz rengiyle bilinen karstik göl hangisidir?', 'Salda Gölü', ['Gölcük Gölü', 'Acıgöl', 'Tuz Gölü'], 'Salda Gölü kalkerli bir çanakta oluşmuştur; kıyısındaki beyaz hidromanyezit birikintileriyle tanınır.'),
  ('Tuz Gölü\'nün yaz aylarında yüzölçümünün büyük ölçüde küçülmesinin başlıca nedeni nedir?', 'Gölün çok sığ olması ve buharlaşmanın artması', ['Göl suyunun Kızılırmak\'a boşalması', 'Gölün tabanındaki düdenlerden suyun kaçması', 'Kıyılarındaki buzulların erimesi'], 'Ortalama derinliği bir-iki metreyi geçmeyen Tuz Gölü\'nde yazın şiddetli buharlaşma geniş alanları kurutarak tuz tabakası bırakır.'),
  ('Tuz Gölü hangi illerin sınırları arasında yer alır?', 'Ankara, Konya ve Aksaray', ['Konya, Karaman ve Niğde', 'Ankara, Kırşehir ve Nevşehir', 'Eskişehir, Afyonkarahisar ve Konya'], 'Tuz Gölü İç Anadolu\'nun ortasında bu üç ilin birleştiği alandaki tektonik çanaktadır.'),
  ('Van Gölü ile Tuz Gölü karşılaştırıldığında aşağıdakilerden hangisi doğrudur?', 'Van Gölü daha derindir.', ['Tuz Gölü daha büyüktür.', 'Van Gölü daha alçakta yer alır.', 'Tuz Gölü bir lav seti gölüdür.'], 'Van Gölü yüzlerce metre derinliğe ulaşırken Tuz Gölü çok sığdır; Van Gölü hem daha büyük hem de daha yüksektedir.'),
  ('Dar ve derin vadilerin baraj yapımına elverişli olmasının nedeni nedir?', 'Kısa bir gövdeyle büyük miktarda suyun tutulabilmesi', ['Bu vadilerde buharlaşmanın çok yüksek olması', 'Bu vadilerin tamamen düz olması', 'Bu vadilerde yağışın hiç görülmemesi'], 'Dar boğazlarda gövde kısa tutulabilir; derin vadi arkasında ise geniş hacimli bir göl birikir. Bu, maliyeti düşürür.'),
  ('Bir baraj gölünün zamanla dolarak ömrünü kısaltan doğal süreç hangisidir?', 'Akarsuyun taşıdığı alüvyonun birikmesi', ['Gölün tuzlanması', 'Göl suyunun donması', 'Gölün volkanik lavla kapanması'], 'Akarsuyun getirdiği kum ve mil göl tabanında birikir; havzada erozyon fazlaysa göl hacmi hızla azalır.'),
  ('İstanbul\'daki Küçükçekmece Gölü\'nün oluşumu nasıl açıklanır?', 'Kıyı okunun bir koyun önünü kapatması', ['Bir fayın çökmesi', 'Volkan kraterinin dolması', 'Bir buzul sirkinin dolması'], 'Küçükçekmece Gölü Marmara kıyısında koyu denizden ayıran kıyı setinin oluşturduğu bir lagündür.'),
  ('Lagün göllerinin suyunun genellikle acı ya da hafif tuzlu olmasının nedeni nedir?', 'Deniz suyuyla bağlantı ya da karışmanın sürmesi', ['Akarsuların hiç ulaşmaması', 'Volkanik gazların suya karışması', 'Tabandaki kalkerin çözünmesi'], 'Lagünler denizden yeni ayrılmış ya da dar bir geçitle denize açılan göllerdir; tatlı ve tuzlu su karışır.'),
  ('Yeraltı suyunun basınçla kendiliğinden yüzeye fışkırdığı kuyulara ne ad verilir?', 'Artezyen', ['Obruk', 'Düden', 'Vokluz'], 'Artezyen kuyularında iki geçirimsiz tabaka arasında basınç altında bulunan su, açılan kuyudan kendiliğinden yükselir.'),
  ('Birbirine yakın enlemlerde bulunan Trabzon ile Erzurum\'da kış sıcaklıklarının çok farklı olmasının başlıca iki nedeni hangisinde birlikte verilmiştir?', 'Yükselti ve denizellik', ['Enlem ve güneşlenme süresi', 'Boylam ve bakı durumu', 'Bakı ve yerel saat farkı'], 'Trabzon deniz kıyısında ve alçakta, Erzurum ise yaklaşık 1.900 metrede ve iç kesimdedir; bu nedenle Erzurum kışın çok daha soğuktur.'),
  ('Deniz seviyesinde ortalama sıcaklığı 20 °C olan bir yerle aynı enlemdeki 1.800 m yükseltideki bir yerin ortalama sıcaklığı, her 200 m\'de 1 °C azalma kabul edilirse kaç °C olur?', '11 °C', ['9 °C', '13 °C', '2 °C'], '1.800 ÷ 200 = 9 °C azalma olur; 20 - 9 = 11 °C bulunur.'),
  ('Aşağıdakilerden hangisi Türkiye\'de iklim çeşitliliğinin nedenleri arasında yer almaz?', 'Ülkenin doğu yarım kürede yer alması', ['Yükseltinin kısa mesafede değişmesi', 'Dağların kıyıya paralel uzanması', 'Üç tarafının denizlerle çevrili olması'], 'Doğu ya da batı yarım kürede olmak iklimi belirlemez; çeşitliliği yükselti, dağların uzanışı ve deniz etkisi yaratır.'),
  ('Ocak ayında Türkiye\'de sıcaklığın genel olarak batıdan doğuya doğru azalmasının temel nedeni hangisidir?', 'Doğuya doğru yükseltinin artması', ['Doğuya doğru enlemin artması', 'Doğuya doğru denize yaklaşılması', 'Doğuya doğru güneşlenme süresinin uzaması'], 'Türkiye\'de ortalama yükselti batıdan doğuya artar; bu da kış sıcaklıklarının doğuda daha düşük olmasına yol açar.'),
  ('İç Anadolu\'da gece ile gündüz arasındaki sıcaklık farkının yazın fazla olmasının nedeni nedir?', 'Havanın kuru ve açık olması', ['Bölgenin deniz seviyesinde bulunması', 'Bölgenin çok yağış alması', 'Bölgenin sık ormanlarla örtülü olması'], 'Nem ve bulut azlığı gündüz güçlü ısınmaya, gece ise ısının uzaya hızla yayılmasına izin verir.'),
  ('Marmara Bölgesi\'nde kışın zaman zaman ani soğumalar ve kar yağışları görülmesinin nedeni hangisidir?', 'Kuzeyden gelen soğuk havaya açık olması', ['Bölgenin kapalı havza olması', 'Bölgenin çok yüksek olması', 'Güneyden gelen sıcak hava kütlelerinin hiç ulaşmaması'], 'Marmara\'nın kuzeyinde soğuk havayı engelleyecek yüksek dağlar bulunmaz; Balkanlar ve Karadeniz üzerinden gelen hava kütleleri doğrudan etkili olur.'),
  ('Türkiye\'de kış yağışlarının büyük kısmı hangi yağış türüyle gerçekleşir?', 'Cephesel', ['Konveksiyonel', 'Yalnız orografik', 'Muson kaynaklı'], 'Kışın İzlanda alçak basıncının etkisiyle sıcak ve soğuk hava kütleleri karşılaşır; oluşan cepheler yağış bırakır.'),
  ('Kuzeybatıdan esen ve kışın soğuk hava ile kar yağışı getiren rüzgâr hangisidir?', 'Karayel', ['Kıble', 'Gün doğusu', 'Keşişleme'], 'Karayel Balkanlar üzerinden kuzeybatıdan esen soğuk rüzgârdır.'),
  ('Güneydoğudan esen yerel rüzgârın adı nedir?', 'Keşişleme', ['Karayel', 'Poyraz', 'Gün batısı'], 'Keşişleme güneydoğudan esen rüzgârdır; adı Uludağ\'ın eski adı Keşiş Dağı\'ndan gelir.'),
  ('İzmir\'de yaz öğleden sonraları denizden karaya esen ve şehri serinleten rüzgâr hangisidir?', 'İmbat', ['Lodos', 'Samyeli', 'Poyraz'], 'İmbat, yazın gündüz karanın denizden çabuk ısınmasıyla oluşan denizden karaya doğru esen serin meltemdir.'),
  ('Güneydoğu Anadolu\'da yazın esen sıcak, kuru ve tozlu rüzgâra ne ad verilir?', 'Samyeli', ['İmbat', 'Karayel', 'Keşişleme'], 'Samyeli Suriye çöllerinden gelir; ekinleri kurutarak tarıma zarar verebilir.'),
  ('Yaz aylarında Türkiye\'nin güney ve güneydoğu kesimlerinde sıcak ve kuru havanın etkili olmasının nedeni olan basınç merkezi hangisidir?', 'Basra Alçak Basıncı', ['İzlanda Alçak Basıncı', 'Sibirya Yüksek Basınç Merkezi', 'Aleut Alçak Basıncı'], 'Basra Körfezi çevresinde yazın oluşan termik alçak basınç, güneyden sıcak ve kuru havayı Türkiye\'ye çeker.'),
  ('Karadeniz kıyılarında yaz aylarında bile bulutluluğun fazla olmasının sonucu aşağıdakilerden hangisidir?', 'Güneşlenme süresinin kısa olması', ['Kıyıda tuzlanmanın artması', 'Bitki örtüsünün maki olması', 'Akarsuların yazın kuruması'], 'Sık bulutluluk güneş ışınlarının yere ulaşmasını azaltır; bu da güneşlenme süresini kısaltır ve sıcaklıkları düşük tutar.'),
  ('Ocak ortalaması 10 °C, temmuz ortalaması 28 °C olan; yağışın büyük kısmını kışın alan ve yazı kurak geçen bir istasyonun iklimi hangisidir?', 'Akdeniz iklimi', ['Karadeniz iklimi', 'İç Anadolu karasal iklimi', 'Doğu Anadolu sert karasal iklimi'], 'Ilık kış, sıcak ve kurak yaz ile kış yağış maksimumu Akdeniz ikliminin tipik özellikleridir.'),
  ('Ege kıyılarında Akdeniz ikliminin iç kesimlere doğru daha fazla sokulabilmesinin nedeni nedir?', 'Dağların kıyıya dik uzanması', ['Ege\'nin Akdeniz\'den daha sıcak olması', 'Ege kıyılarının daha yüksek olması', 'Ege\'de rüzgârların hiç esmemesi'], 'Ege\'de dağlar denize dik uzandığından deniz etkisi grabenler boyunca iç kesimlere kadar ulaşır.'),
  ('Akdeniz Bölgesi\'nde kıyıdan Toroslar\'ın yüksek kesimlerine çıkıldıkça iklimin değişmesinin temel nedeni nedir?', 'Yükseltinin artması', ['Enlemin hızla artması', 'Boylamın değişmesi', 'Denizin ılıtıcı etkisinin yükseklerde artması'], 'Kısa mesafede binlerce metre yükselinir; yükseltiyle sıcaklık düşer, kışlar karlı ve sert hâle gelir.'),
  ('İç Anadolu\'da görülen karasal iklimin yağış bakımından en belirgin özelliği nedir?', 'Yağışın az ve en çok ilkbaharda düşmesi', ['Yağışın her mevsim bol olması', 'Yağışın yalnız yazın görülmesi', 'Yağışın büyük kısmının sonbaharda düşmesi'], 'İç Anadolu yağış gölgesindedir; yıllık yağış genellikle 300-500 mm arasındadır ve ilkbaharda en yüksek düzeye ulaşır.'),
  ('Ocak ortalaması -9 °C, temmuz ortalaması 19 °C olan ve kar örtüsünün aylarca yerde kaldığı bir istasyon aşağıdakilerden hangisi olabilir?', 'Erzurum', ['Adana', 'Samsun', 'Muğla'], 'Kış ortalamasının sıfırın çok altında, yazın ise serin olması sert karasal iklimi gösterir; Erzurum bu iklimin tipik örneğidir.'),
  ('Güneydoğu Anadolu\'nun ikliminin karasal olmakla birlikte yağışlarını büyük ölçüde kışın alması neyin etkisini gösterir?', 'Akdeniz ikliminin', ['Karadeniz ikliminin', 'Muson ikliminin', 'Kutup ikliminin'], 'Güneydoğu\'ya kışın Akdeniz üzerinden gelen cepheler yağış bırakır; yazlar ise çok sıcak ve kuraktır.'),
  ('Marmara Bölgesi\'nin ikliminin geçiş özelliği göstermesinin nedeni nedir?', 'Üç farklı iklimin etki alanı arasında kalması', ['Bölgenin tamamının aynı yükseltide bulunması', 'Bölgeye hiç deniz etkisi ulaşmaması', 'Bölgenin dağlarla tamamen çevrili olması'], 'Marmara\'nın kuzeyi Karadeniz, güneyi Akdeniz, iç kesimi ise karasal iklimden etkilenir; bu yüzden geçiş iklimi görülür.'),
  ('İki istasyondan A\'nın yıllık sıcaklık farkı 30 °C, B\'nin 13 °C\'dir. Bu bilgiye göre hangi yorum yapılabilir?', 'A daha karasal bir yerdir.', ['B iç kesimde, A deniz kıyısındadır.', 'B\'de kışlar A\'dan daha soğuktur.', 'A\'nın yağışı mutlaka B\'den fazladır.'], 'Yıllık sıcaklık farkının büyük olması karasallığın göstergesidir; diğer yorumlar bu veriden çıkarılamaz.'),
  ('Step bitki örtüsünün İç Anadolu\'da yaygın olması iklim açısından nasıl açıklanır?', 'Yağışın ağaç için yetersiz olması', ['Yazların serin ve nemli geçmesi', 'Toprağın her mevsim donmuş olması', 'Kışların ılık ve yağışlı olması'], 'Az yağışlı karasal iklimde ilkbahar yağışlarıyla yeşeren, yazın kuruyan otsu bitkiler gelişir; buna step denir.'),
  ('Makilerin tahrip edildiği alanlarda yerini alan, daha seyrek ve kısa boylu bitki topluluğu hangisidir?', 'Garig', ['Tayga', 'Savan', 'Psödomaki'], 'Makinin kesilip yakıldığı yerlerde kekik ve adaçayı gibi bodur bitkilerden oluşan garig gelişir.'),
  ('Karadeniz kıyılarındaki alçak kesimlerde yaygın olan ormanların türü nedir?', 'Geniş yapraklı nemli ormanlar', ['İğne yapraklı kuru ormanlar', 'Maki toplulukları', 'Kuraklığa dayanıklı otsu step toplulukları'], 'Kayın, gürgen, kestane, ıhlamur ve kızılağaç gibi ağaçlar Karadeniz\'in alçak ve orta kesimlerinde gür ormanlar oluşturur.'),
  ('Doğu Karadeniz\'de yükseldikçe geniş yapraklı ağaçların yerini alan iğne yapraklı ağaçlar hangisinde birlikte verilmiştir?', 'Ladin ve köknar', ['Kızılçam ve fıstık çamı', 'Sedir ve ardıç', 'Zeytin ve keçiboynuzu'], 'Sıcaklığın azaldığı yüksek kesimlerde soğuğa dayanıklı ladin ve köknar ormanları yayılır.'),
  ('Karadeniz\'in yüksek kesimlerinde iğne yapraklı ormanlar altında oluşan, aşırı yıkanmış ve asitli toprak hangisidir?', 'Podzol', ['Terra rossa', 'Çernozyom', 'Alüvyal toprak'], 'Bol yağış toprak içindeki mineralleri alt katmanlara taşır; iğne yaprakların asitli çürümesiyle gri renkli podzol oluşur.'),
  ('Kapalı havzalarda ve yetersiz drenajlı ovalarda görülen tuzlanmanın (çoraklaşmanın) temel nedeni nedir?', 'Buharlaşmayla tuzların yüzeyde kalması', ['Toprağın aşırı yağışla yıkanması', 'Toprakta humusun çok artması', 'Akarsuların tuzları denize taşıması'], 'Kurak ortamda kılcal yollarla yükselen su buharlaşır, içindeki tuzlar toprak yüzeyinde kalır.'),
  ('Rüzgârın taşıdığı ince tozların birikmesiyle oluşan, sarımsı renkli toprak türü hangisidir?', 'Lös', ['Moren', 'Kolüvyal toprak', 'Rendzina'], 'Lös rüzgâr biriktirmesiyle oluşan, gözenekli ve verimli bir topraktır.'),
  ('İç Anadolu\'nun step alanlarında yaygın olan, humusu orta düzeyde bulunan toprak tipi hangisidir?', 'Kahverengi step toprakları', ['Podzol toprakları', 'Kırmızı Akdeniz toprakları', 'Kahverengi orman toprakları'], 'Yarı kurak iklimde otsu bitkilerin sınırlı humus bıraktığı kahverengi step toprakları gelişir.'),
  ('Türkiye\'de günümüzde vadi buzullarının en gelişmiş olduğu dağlık alan hangisidir?', 'Cilo-Sat Dağları', ['Uludağ', 'Erciyes Dağı', 'Ilgaz ve Köroğlu Dağları'], 'Hakkâri\'deki Cilo-Sat Dağları\'nda güneydoğu konumuna rağmen yükseltinin fazlalığı nedeniyle vadi buzulları bulunur.'),
  ('Ağrı Dağı\'nın zirvesini örten buzul hangi tiptedir?', 'Takke buzulu', ['Vadi buzulu', 'Kıta (örtü) buzulu', 'Sirk buzulu'], 'Ağrı Dağı\'nın konik zirvesini başlık gibi saran buzul takke buzulu olarak adlandırılır.'),
  ('Rüzgârın taşıdığı kum tanelerinin kayaları alt kısımdan daha çok aşındırmasıyla oluşan şekil hangisidir?', 'Mantar kaya', ['Peribacası', 'Lapya', 'Dalga aşınım çentiği'], 'Rüzgâr kumu yere yakın taşıdığından kayanın tabanı daha fazla aşınır; üstü geniş, altı dar mantar kayalar oluşur.'),
  ('Kapadokya\'daki peribacalarının üstündeki şapka biçimli kayanın görevi nedir?', 'Alttaki tüfü aşınmadan korumak', ['Volkanik gazların çıkışını sağlamak', 'Yağmur sularını tüfün içine toplamak', 'Tüf katmanlarını birbirine yapıştırmak'], 'Sert bazalt ya da ignimbrit şapka altındaki tüfü yağmur ve selinti sularından korur; korunmayan çevre aşınınca kule biçimli peribacası kalır.'),
  ('Peribacalarının oluşumunda en etkili dış kuvvet aşağıdakilerden hangisidir?', 'Sel ve yağmur suları', ['Buzullar', 'Kıyı dalgaları', 'Yer altı suları ve kaynaklar'], 'Kapadokya\'da yağmur suları ve sağanak sonrası selinti suları yumuşak tüfü oyarak peribacalarını şekillendirmiştir; rüzgârın etkisi ikincildir.'),
  ('Aksaray\'da Melendiz Çayı\'nın volkanik tüfleri derince yarmasıyla oluşan vadi hangisidir?', 'Ihlara Vadisi', ['Saklıkent Kanyonu', 'Köprülü Kanyon', 'Valla Kanyonu'], 'Ihlara Vadisi Hasan Dağı ve Melendiz volkanlarının tüfleri içinde açılmış dik yamaçlı bir kanyondur.'),
  ('Akarsuların dağdan ovaya çıktığı yerde eğimin azalmasıyla biriktirdiği yelpaze biçimli şekle ne ad verilir?', 'Birikinti konisi', ['Delta', 'Menderes', 'Kırgıbayır yüzeyi'], 'Eğim birden azalınca akarsu taşıma gücünü yitirir ve malzemeyi yelpaze biçiminde dağ eteğine yığar.'),
  ('Akarsu yatağındaki girdapların taşları döndürerek kayada açtığı çukurlara ne ad verilir?', 'Dev kazanı', ['Obruk', 'Dolin', 'Buzul sirki'], 'Dev kazanları özellikle şelale ve çağlayanların dibinde, suyun dönerek taşları sürtmesiyle oluşur.'),
  ('Akarsu yataklarında şelalelerin çoğunlukla sert ve yumuşak kayaçların art arda dizildiği yerlerde oluşmasının nedeni nedir?', 'Yumuşak kayacın daha hızlı aşınması', ['Sert kayacın suyu hızla emmesi', 'Yumuşak kayacın akarsuyu yukarı itmesi', 'İki kayacın da hiç aşınmaması'], 'Sert katman aşınmaya direnirken altındaki ya da önündeki yumuşak katman hızla aşınır; yatakta basamak oluşur ve su buradan düşer.'),
  ('Antalya\'da suları doğrudan denize dökülen şelale hangisidir?', 'Aşağı Düden Şelalesi', ['Kurşunlu Şelalesi', 'Manavgat Şelalesi', 'Yukarı Düden Şelalesi'], 'Düden Çayı Lara yakınında falezlerden doğrudan Akdeniz\'e dökülerek Aşağı Düden Şelalesi\'ni oluşturur.'),
  ('Akarsuların derine aşındırmasıyla dar ve dik yamaçlı derin vadilerin oluşması için en uygun koşul hangisidir?', 'Yatak eğiminin fazla olması', ['Akarsuyun deltaya ulaşması', 'Akarsuyun gölde son bulması', 'Akarsuyun taban seviyesine yaklaşması'], 'Eğim arttıkça suyun hızı ve aşındırma gücü artar; akarsu yatağını derinleştirerek kanyon gibi dar vadiler açar.'),
  ('Türkiye\'nin ortalama yükseltisinin yaklaşık 1.100 metre olması Avrupa ortalamasıyla karşılaştırıldığında ne gösterir?', 'Türkiye\'nin belirgin biçimde yüksek olduğunu', ['Türkiye\'nin Avrupa ile aynı yükseltide olduğunu', 'Türkiye\'nin Avrupa\'dan daha alçak olduğunu', 'Türkiye\'de bölgeler arasında hiç yükselti farkı bulunmadığını'], 'Avrupa\'nın ortalama yükseltisi 300 metrenin biraz üzerindedir; Türkiye bunun yaklaşık üç katıdır.'),
  ('Türkiye\'de eğimin fazla olmasının akarsular üzerindeki olumlu etkisi aşağıdakilerden hangisidir?', 'Enerji potansiyelinin yüksek olması', ['Akarsularda gemi ulaşımının kolaylaşması', 'Akarsuların geniş deltalar oluşturamaması', 'Akarsuların rejimlerinin düzenli olması'], 'Eğimli yataklarda akan su yüksek düşü sağlar; bu da barajlarda elektrik üretimi için avantajdır.'),
  ('Edremit Körfezi\'nin kuzeyinde yer alan, antik çağda İda adıyla bilinen ve oksijen bakımından zengin ormanlarıyla tanınan dağ hangisidir?', 'Kazdağı', ['Uludağ', 'Madra Dağı', 'Spil Dağı'], 'Kazdağı Balıkesir ile Çanakkale arasında uzanır; kuzey ve güney yamaçları arasında belirgin iklim farkı görülür.'),
  ('Trakya\'nın kuzeyinde Karadeniz kıyısına paralel uzanan dağlar hangisidir?', 'Istranca Dağları', ['Ganos Dağı', 'Kazdağı', 'Samanlı Dağları'], 'Istranca Dağları Trakya\'nın kuzeyinde, Bulgaristan sınırından İstanbul\'a doğru uzanır.'),
  ('Manisa\'nın hemen güneyinde yükselen ve Manisa Ovası\'na bakan dağ hangisidir?', 'Spil Dağı', ['Murat Dağı', 'Madra Dağı', 'Kazdağı'], 'Spil Dağı Manisa şehrinin güneyinde yükselir ve milli park olarak korunur.'),
  ('Hakkâri\'de yer alan ve Türkiye\'nin en yüksek ikinci dağı kabul edilen kütle hangisidir?', 'Cilo Dağı', ['Süphan Dağı', 'Erciyes Dağı', 'Kaçkar Dağı'], 'Cilo Dağı\'nın en yüksek zirvesi Uludoruk\'tur; Ağrı Dağı\'ndan sonra Türkiye\'nin en yüksek noktasıdır.'),
  ('Trabzon ile Gümüşhane arasında Doğu Karadeniz Dağları\'nı aşan tarihi geçit hangisidir?', 'Zigana Geçidi', ['Kop Geçidi', 'Gülek Boğazı', 'Belen Geçidi'], 'Zigana Geçidi kıyıdaki Trabzon\'u iç kesimdeki Gümüşhane ve Erzurum\'a bağlayan tarihî İpek Yolu güzergâhı üzerindedir.'),
  ('Tunceli\'de yer alan ve adını taşıyan çayın da kaynağını aldığı yüksek dağ sırası hangisidir?', 'Munzur Dağları', ['Palandöken Dağları', 'Nemrut Dağı', 'Karacadağ'], 'Munzur Dağları Tunceli-Erzincan arasında uzanır; Munzur Çayı bu dağlardaki karstik kaynaklardan doğar.'),
  ('Türkiye\'de dağ sıralarının genellikle doğu-batı doğrultusunda uzanmasının ulaşım üzerindeki sonucu nedir?', 'Kuzey-güney yönlü ulaşımın zorlaşması', ['Doğu-batı yönlü ulaşımın imkânsız hâle gelmesi', 'Bütün yolların kıyıdan geçmek zorunda kalması', 'Ulaşımda yalnız akarsuların kullanılması'], 'Kuzey-güney yönünde ilerleyen yollar sıradağları aşmak zorundadır; bu geçitler ve tünellerle sağlanır.'),
  ('Trakya\'nın iç kesiminde yer alan, Tersiyer tortullarıyla dolmuş geniş çanak hangisidir?', 'Ergene Havzası', ['Adapazarı Ovası', 'Bursa Ovası', 'Bandırma Platosu'], 'Ergene Havzası Istranca Dağları ile Tekirdağ (Ganos) Dağları arasındaki alçak ve dalgalı bir düzlüktür.'),
  ('Kapıdağ Yarımadası\'nın kuzeybatısında toplanan Marmara Adaları grubunun en büyüğü hangisidir?', 'Marmara Adası', ['Avşa Adası', 'Paşalimanı Adası', 'Ekinlik Adası'], 'Marmara Adası mermer ocaklarıyla tanınır ve adı da buradan gelir; Marmara Denizi\'nin en büyük adasıdır.'),
  ('Ege Bölgesi\'nde kıyıdan iç kesime gidildikçe yükseltinin artmasıyla iklimde görülen değişim nedir?', 'Akdeniz ikliminden karasal iklime geçiş', ['Karasal iklimden Akdeniz iklimine geçiş', 'Karadeniz ikliminden Akdeniz iklimine geçiş', 'Muson ikliminden karasal iklime geçiş'], 'Kıyı Ege\'de Akdeniz iklimi görülürken İç Batı Anadolu\'da yükseltinin ve deniz uzaklığının artmasıyla karasallık belirginleşir.'),
  ('Ege Bölgesi\'nin İç Batı Anadolu Bölümü\'nün kıyı kesimden ayrılan fiziki özelliği nedir?', 'Yükseltisinin daha fazla olması', ['Graben ovalarının daha yaygın olması', 'Kışların daha ılık ve yağmurlu geçmesi', 'Maki örtüsünün daha geniş alan kaplaması'], 'İç Batı Anadolu plato ve dağlarla kaplıdır; deniz etkisi azaldığından iklim karasallaşır ve bitki örtüsü step ile kuru ormana döner.'),
  ('Akdeniz Bölgesi\'nin Göller Yöresi\'nde çok sayıda göl bulunmasının nedeni hangisinde doğru verilmiştir?', 'Tektonik ve karstik çanakların bol olması', ['Bölgede buzulların bugün de geniş alanlarda etkili olması', 'Volkanik kraterlerin yoğun olması', 'Kıyı oklarının koyları kapatması'], 'Kırılmalarla oluşan çukurlar ve kalkerin çözündüğü alanlar suların birikmesine elverişli çanaklar oluşturmuştur.'),
  ('İç Anadolu Bölgesi\'nin çevresinin dağlarla kuşatılmış olmasının bölgenin akarsuları üzerindeki etkisi nedir?', 'Kapalı havzaların yaygınlaşması', ['Akarsuların tamamının Akdeniz\'e ulaşması', 'Akarsuların her mevsim taşkın yapması', 'Akarsuların buzullarla beslenmesi'], 'Çevre dağlar suyun dışarı akışını engeller; Tuz Gölü ve Konya havzası gibi iç akışlı çanaklar oluşur.'),
  ('İç Anadolu\'nun güneydoğusunda yer alan Kapadokya yöresinin yer şekillerinin şekillenmesinde etkili olan iç kuvvet hangisidir?', 'Volkanizma', ['Kıvrılma', 'Buzullaşma', 'Deniz ilerlemesi'], 'Erciyes, Hasan ve Melendiz volkanlarının püskürttüğü küller tüf katmanlarını oluşturmuştur; dış kuvvetler bu katmanları aşındırmıştır.'),
  ('İç Anadolu Bölgesi\'nin dörde ayrıldığı bölümlerden biri olmayan seçenek hangisidir?', 'Göller Yöresi Bölümü', ['Konya Bölümü', 'Yukarı Sakarya Bölümü', 'Orta Kızılırmak Bölümü'], 'İç Anadolu; Konya, Yukarı Sakarya, Orta Kızılırmak ve Yukarı Kızılırmak bölümlerine ayrılır. Göller Yöresi Akdeniz Bölgesi\'ndedir.'),
  ('Akdeniz kıyısında kıyı ovası ile Toroslar\'ın zirvesi arasında kısa mesafede farklı bitki kuşaklarının görülmesine ne ad verilir?', 'Dikey kuşaklanma', ['Yatay dağılış', 'Tektonik kuşaklanma', 'Enlemsel geçiş'], 'Yükselti arttıkça sıcaklığın düşmesiyle maki, kızılçam, karaçam-sedir ve dağ çayırı kuşakları yukarıya doğru sıralanır.'),
  ('Doğu Anadolu Bölgesi\'nin Türkiye\'nin en yüksek bölgesi olmasının jeolojik nedeni nedir?', 'Sıkışma ile yükselme ve volkanizma', ['Bölgenin eski bir aşınım düzlüğü olması', 'Bölgenin akarsu birikimiyle yükselmesi', 'Bölgenin buzul birikintileriyle örtülmesi'], 'Arap levhasının kuzeye ilerlemesi bölgeyi sıkıştırarak yükseltmiş; volkanik dağlar ve lav platoları yükseltiyi daha da artırmıştır.'),
  ('Güneydoğu Anadolu\'nun ortalama yükseltisinin Doğu Anadolu\'dan çok daha az olmasının yer şekilleri üzerindeki sonucu nedir?', 'Plato ve ovaların geniş yer tutması', ['Buzul şekillerinin yaygınlaşması', 'Akarsuların kısa ve şelaleli olması', 'Çok sayıda volkanik krater gölünün bulunması'], 'Bölge Mezopotamya\'ya doğru alçalır; bu nedenle platolar ve geniş ovalar baskındır.'),
  ('Karadeniz\'in tuzluluk oranının Akdeniz\'e göre çok düşük olmasının iki temel nedeni hangisinde birlikte verilmiştir?', 'Bol akarsu girişi ve az buharlaşma', ['Yüksek sıcaklık ve fazla buharlaşma', 'Kapalı havza olması ve az yağış', 'Derin olması ve akarsu girişinin az olması'], 'Tuna, Dinyeper, Don gibi büyük akarsular ile kıyıdaki dereler bol tatlı su getirir; serin iklim nedeniyle buharlaşma da azdır.'),
  ('Ege Denizi\'nin çok sayıda ada içermesinin oluşum bakımından nedeni nedir?', 'Çöken Egeid karasının yüksek kesimlerinin su üstünde kalması', ['Volkanik patlamaların denizin ortasında yeni kara oluşturması', 'Akarsu deltalarının denize doğru büyümesi', 'Buzulların bıraktığı morenlerin birikmesi'], 'Egeid karası kırılıp çökerken yüksek blokların tepeleri ada olarak su yüzünde kalmıştır.'),
  ('Türkiye kıyılarında gel-git olayının belirgin biçimde görülmemesinin nedeni nedir?', 'Denizlerin okyanuslardan uzak ve kapalı olması', ['Kıyıların çok yüksek ve dik dağlarla çevrili olması nedeniyle', 'Denizlerin tuzluluğunun düşük olması', 'Ay\'ın Türkiye\'yi etkilememesi'], 'Gel-git genliği açık okyanuslarda büyüktür; Akdeniz ve Karadeniz gibi iç denizlerde birkaç santimetre ile sınırlı kalır.'),
  ('Batı Karadeniz\'de Kuzey Anadolu Fay Hattı üzerinde bulunan ve çöküntü kökenli olan ova hangisidir?', 'Düzce Ovası', ['Bafra Ovası', 'Çarşamba Ovası', 'Ergene Havzası düzlükleri'], 'Düzce Ovası fay boyunca çöken bir alanın alüvyonla dolmasıyla oluşmuştur; Bafra ve Çarşamba ise delta ovalarıdır.'),
  ('Muğla\'da Köyceğiz Gölü\'nün sularını Akdeniz\'e ulaştıran ve kıyısında kaya mezarları bulunan kanal hangisidir?', 'Dalyan Kanalı', ['Eşen Çayı', 'Dalaman Çayı', 'Aksu Çayı'], 'Köyceğiz Gölü\'nün suları dar ve kıvrımlı Dalyan Kanalı aracılığıyla İztuzu kumsalında denize ulaşır.'),
  ('Kayseri\'nin Develi ilçesinde yer alan ve kuş göç yolları üzerindeki önemli bir sulak alan olan saha hangisidir?', 'Sultan Sazlığı', ['Seyfe Gölü', 'Uzungöl', 'Kızılırmak deltası'], 'Sultan Sazlığı kapalı bir havzada tatlı ve tuzlu suların birleştiği sazlık ve göllerden oluşur; Ramsar alanıdır.'),
  ('Afyonkarahisar ile Konya arasında yer alan ve tektonik kökenli olan göl çifti hangisidir?', 'Eber ve Akşehir gölleri', ['Sapanca ve İznik gölleri', 'Çıldır ve Aktaş gölleri', 'Mogan ve Eymir gölleri'], 'Eber ve Akşehir gölleri Sultan Dağları\'nın kuzeyindeki çöküntü alanında bulunan tektonik göllerdir.'),
  ('Doğu Anadolu\'daki göllerin kışın uzun süre donmasının temel nedeni nedir?', 'Yükseltinin fazlalığı ve karasal iklim', ['Göllerin çok tuzlu olması', 'Göllerin denize bağlantılı olması', 'Göllerin bulunduğu yerin deniz seviyesine yakın olması'], 'Yüksek ve karasal Doğu Anadolu\'da kış sıcaklıkları uzun süre sıfırın altında kalır; Çıldır Gölü gibi tatlı göllerin yüzeyi donar.'),
  ('Van Gölü\'nün kışın büyük ölçüde donmamasının nedeni aşağıdakilerden hangisidir?', 'Suyunun sodalı olması', ['Deniz seviyesinde bulunması', 'Göle sıcak akarsuların dolması', 'Gölün çok sığ olması'], 'Çözünmüş madde oranı yüksek suların donma noktası düşüktür; ayrıca büyük hacim ısıyı uzun süre korur.'),
  ('Göllerin kurumasına ya da alanının küçülmesine yol açan insan etkinliği aşağıdakilerden hangisidir?', 'Suların sulamada aşırı tüketilmesi', ['Göl çevresinde ağaçlandırma yapılması', 'Gölü besleyen kaynakların korunması', 'Havzada erozyon önleme çalışmaları yapılması'], 'Göle ulaşması gereken akarsu ve yeraltı suları sulamada tüketildiğinde göl seviyesi düşer; Akşehir ve Eber gölleri bu sorunu yaşamıştır.'),
  ('Kuzey Afrika kökenli tropikal karasal hava kütlesinin Türkiye\'ye ulaştığı günlerde hangi durum beklenir?', 'Sıcak, kuru ve tozlu hava', ['Yoğun kar yağışı görülmesi', 'Sıcaklığın sıfırın altına inmesi', 'Bulutluluğun ve sisin artması'], 'Çöl kökenli bu hava kütlesi sıcak ve kurudur; beraberinde çöl tozu taşıyarak gökyüzünü bulanıklaştırabilir.'),
  ('Kışın Akdeniz üzerinde oluşan alçak basınç sistemlerinin Türkiye\'ye etkisi nedir?', 'Güney ve batı kıyılarında yağış getirmesi', ['Doğu Anadolu\'da yazı uzatması', 'Karadeniz\'de kuraklığa yol açması', 'İç Anadolu\'da sıcaklığı 30 °C\'nin üzerine çıkarması'], 'Kışın Akdeniz üzerindeki alçak basınçlar cephesel yağış sistemleri oluşturur ve Akdeniz-Ege kıyılarına bol yağış bırakır.'),
  ('Türkiye\'de kış mevsiminde kuzeyde yüksek, güneyde alçak basınç bulunmasının rüzgârlar üzerindeki sonucu nedir?', 'Rüzgârların genellikle kuzeyden esmesi', ['Rüzgârların hep güneyden esmesi', 'Rüzgârların hiç esmemesi', 'Rüzgârların yalnız doğu-batı yönünde esmesi'], 'Rüzgâr yüksek basınçtan alçak basınca doğru eser; bu nedenle kışın kuzeyli rüzgârlar (poyraz, karayel) sık görülür.'),
  ('Iğdır Ovası\'nın Doğu Anadolu\'daki çevresine göre daha ılıman bir iklime sahip olmasının temel nedeni nedir?', 'Çevresinden alçak bir çukurda bulunması', ['Karadeniz\'e kıyısının olması', 'Akdeniz\'e çok yakın olması', 'Kuzeyden gelen soğuk rüzgârlara tamamen açık olması'], 'Iğdır Ovası yaklaşık 850 metre yükseltide, çevresindeki yüksek platolara göre alçak bir çanaktır; bu nedenle kendine özgü bir mikroklima oluşur.'),
  ('Artvin\'de Çoruh Vadisi boyunca zeytin gibi sıcak iklim bitkilerinin yetişebilmesi hangi kavramla açıklanır?', 'Mikroklima', ['Sıcaklık terselmesi', 'Yağış gölgesi ve karasallık', 'Dikey kuşaklanmanın tersine dönmesi'], 'Dar vadiler çevreden farklı, daha ılık ve korunaklı bir yerel iklim oluşturur; buna mikroklima denir.'),
  ('Kuzey Anadolu Dağları\'nda kalıcı kar sınırının kuzey yamaçlarda güney yamaçlara göre daha alçakta olmasının nedeni nedir?', 'Kuzey yamaçların daha az güneş alması', ['Kuzey yamaçların daha sıcak olması', 'Kuzey yamaçlarda yağışın güneye göre daha az olması', 'Kuzey yamaçların daha yüksek olması'], 'Gölgede kalan kuzey yamaçlar daha serindir ve bol yağış alır; bu nedenle karlar daha alçak seviyelerde yaz boyunca erimeden kalabilir.'),
  ('Güney yönünden esen ve Akdeniz üzerinden geldiği için genellikle ılık olan yerel rüzgâr hangisidir?', 'Kıble', ['Yıldız', 'Karayel', 'Poyraz'], 'Kıble güneyden esen rüzgârdır; Akdeniz yönünden geldiği için ılık hava taşır. Yıldız kuzeyden, karayel kuzeybatıdan, poyraz kuzeydoğudan eser.'),
  ('Doğu Karadeniz\'de kışın güneyden esen fön rüzgârlarının kıyıda yol açabileceği durum aşağıdakilerden hangisidir?', 'Karların hızla erimesi', ['Kıyıda yoğun kar yağışı başlaması', 'Deniz suyunun donması', 'Bağıl nemin yükselip sis oluşması'], 'Dağlardan inerken ısınan kuru fön havası kıyıda sıcaklığı birkaç saatte belirgin biçimde artırır ve karları eritir.'),
  ('Ege kıyılarında yaz aylarında kuzeyden düzenli esen rüzgârların etkisi aşağıdakilerden hangisidir?', 'Sıcaklığı bir ölçüde hafifletmeleri', ['Yaz yağışlarını artırmaları', 'Deniz suyunu dondurmaları', 'Kıyıda yaz boyunca sürekli yoğun sis oluşturmaları'], 'Yazın kuzeyli rüzgârlar Ege\'de sıcaklığı bir miktar düşürür; aynı zamanda orman yangınlarının hızla yayılmasına da yol açabilir.'),
  ('Dalgaların aşındırdığı falezin önünde, deniz tabanında oluşan hafif eğimli düzlüğe ne ad verilir?', 'Abrazyon platformu', ['Kıyı oku', 'Akarsu birikinti düzlüğü', 'Tombolo'], 'Falez geriledikçe önünde dalga aşındırmasıyla düzleşmiş bir kaya tabanı kalır; buna abrazyon (aşınım) platformu denir.'),
  ('Muğla\'da Dalyan Kanalı\'nın denize açıldığı yerde uzanan ve deniz kaplumbağalarının yumurtlama alanı olarak korunan kumsal hangisidir?', 'İztuzu', ['Patara', 'Kleopatra Plajı', 'Ölüdeniz'], 'İztuzu Kumsalı kıyı oku biçimindeki bir kum setidir; Caretta caretta kaplumbağaları burada yumurta bırakır.'),
  ('Çanakkale Boğazı\'nın İstanbul Boğazı\'na göre bir farkı aşağıdakilerden hangisidir?', 'Daha uzun olması', ['Karadeniz ile Marmara\'yı birleştirmesi', 'Kuzey Anadolu Fayı\'nın tam ortasından geçmesi', 'Haliç gibi bir ria koyu barındırması'], 'Çanakkale Boğazı yaklaşık 60 km, İstanbul Boğazı ise yaklaşık 30 km uzunluğundadır; Haliç İstanbul\'dadır.'),
  ('Ayvalık önlerinde yer alan ve bir köprüyle karaya bağlanan ada hangisidir?', 'Cunda Adası', ['Bozcaada', 'Uzunada', 'Marmara Adası'], 'Cunda Adası Ayvalık Adaları\'nın en büyüğüdür; kısa bir dolgu ve köprüyle karaya bağlanmıştır.'),
  ('Ege kıyısında Bodrum Yarımadası\'nın güneyinde uzanan ve dar uzun biçimiyle bilinen körfez hangisidir?', 'Gökova Körfezi', ['Kuşadası Körfezi', 'Edremit Körfezi', 'Saros Körfezi'], 'Gökova Körfezi Bodrum Yarımadası ile Datça Yarımadası arasında doğuya doğru uzanır.'),
  ('Bursa\'nın kıyısında, Marmara\'nın güneydoğusunda yer alan ve Orhangazi\'ye doğru uzanan körfez hangisidir?', 'Gemlik Körfezi', ['İzmit Körfezi', 'Erdek Körfezi', 'Bandırma Körfezi'], 'Gemlik Körfezi Armutlu Yarımadası\'nın güneyinde Marmara\'ya açılan tektonik kökenli bir körfezdir.'),
  ('Edremit Körfezi\'nin kuzeyindeki yüksek dağın körfez kıyısındaki iklime etkisi aşağıdakilerden hangisidir?', 'Kuzeyden gelen soğuk havayı engellemesi', ['Körfeze bol kar yağışı getirmesi', 'Körfezi kapalı bir göle dönüştürmesi', 'Körfezde gel-git olayının genliğini belirgin biçimde artırması'], 'Kazdağı kuzey rüzgârlarına karşı perde oluşturur; körfez kıyısı ılıman bir yerel iklime sahiptir.'),
  ('Kula ve Karacadağ çevresinde yaygın olan, akışkan lavların hızla soğumasıyla oluşan koyu renkli volkanik kayaç hangisidir?', 'Bazalt', ['Granit', 'Mermer', 'Kristalize kalker'], 'Bazalt silisçe fakir, akışkan lavların yüzeyde soğumasıyla oluşur; Karacadağ ve Kula\'da geniş örtüler hâlindedir.'),
  ('Bir bölgenin geniş alanlarda kıvrılmadan, toptan yükselmesi ya da alçalmasına ne ad verilir?', 'Epirojenez', ['Orojenez', 'Volkanizma', 'Kıyı aşınımı'], 'Epirojenez kıta ölçeğinde yavaş dikey hareketlerdir; orojenez ise kıvrılma ve kırılmalarla dağ oluşumudur.'),
  ('Volkanik etkinliğin Türkiye\'deki yer şekillerine katkısı olarak aşağıdakilerden hangisi gösterilemez?', 'Göller Yöresi\'ndeki polyeler', ['Erzurum-Kars yöresindeki lav platosu', 'Kapadokya\'nın tüf örtüsü', 'Van Gölü\'nün lav seti'], 'Polyeler kalkerin çözünmesiyle oluşan karstik şekillerdir; diğerleri volkanizmanın ürünüdür.'),
  ('Volkanik toprakların çoğu zaman verimli olmasının nedeni nedir?', 'Mineral bakımından zengin olmaları', ['Hiç su tutmamaları', 'Tuz oranlarının yüksek olması', 'Humusun yağışla tamamen yıkanıp yok olması'], 'Volkanik kül ve lavlar ayrıştıkça potasyum, fosfor gibi bitki besinlerini toprağa kazandırır.'),
  ('Türkiye\'de sönmüş volkanların bulunduğu yerler ile fay hatlarının dağılışı karşılaştırıldığında nasıl bir ilişki görülür?', 'Volkanlar çoğunlukla kırık hatlarındadır.', ['Volkanlar yalnız karstik alanlarda bulunur.', 'Volkanlar ile faylar arasında hiçbir ilişki yoktur.', 'Volkanlar yalnız deniz kıyılarında bulunur.'], 'Kırıklar magmanın yükselmesi için yol oluşturur; Kapadokya, Kula ve Doğu Anadolu volkanları fay sistemleriyle ilişkilidir.'),
  ('Bir akarsuyun eski yatak tabanlarının, akarsu derine aşındırdıkça vadi yamaçlarında basamaklar hâlinde kalmasına ne ad verilir?', 'Akarsu taraçası', ['Birikinti konisi', 'Menderes kıvrımı', 'Delta kıyı oku'], 'Taban seviyesi düşünce akarsu yatağını derinleştirir; eski taban düzlükleri yamaçlarda taraça olarak kalır.'),
  ('Akarsu aşındırmasıyla oluşan vadilerin genellikle V biçimli olmasının nedeni nedir?', 'Derine aşındırmanın baskın olması', ['Buzulun tabanı genişletmesi', 'Rüzgârın yamaçları düzleştirmesi', 'Dalgaların vadi tabanını doldurması'], 'Akarsu tabanı hızla oyarken yamaçlar daha yavaş gerilediği için kesit V biçimini alır.'),
  ('Bir akarsuyun aşındırabileceği en alt seviyeye ne ad verilir?', 'Taban seviyesi', ['Kar sınırı', 'Su bölümü çizgisi', 'Eş yükselti eğrisi'], 'Denize dökülen akarsular için genel taban seviyesi deniz yüzeyidir; göl ve baraj gölleri yerel taban seviyesi oluşturur.'),
  ('Akarsuyun taşıdığı malzemenin ağza yakın yerlerde daha ince, kaynağa yakın yerlerde daha iri olmasının nedeni nedir?', 'Akarsuyun hızının ağza doğru azalması', ['Akarsuyun ağza doğru hızlanması', 'Malzemenin denizde büyümesi', 'Akarsuyun kaynağında hiç aşındırma yapmaması'], 'Eğim azaldıkça akış hızı ve taşıma gücü düşer; önce iri, sonra ince malzeme birikir.'),
  ('Ankara\'nın güneybatısında, Polatlı ile Gölbaşı arasında uzanan plato hangisidir?', 'Haymana Platosu', ['Bozok Platosu', 'Uzunyayla Platosu', 'Taşeli Platosu'], 'Haymana Platosu Ankara\'nın güneyinde dalgalı bir düzlüktür; tahıl tarımı yapılan geniş alanlar barındırır.'),
  ('Antalya\'nın batısında Teke Yarımadası\'nın iç kesimini oluşturan, kalkerli ve karstik şekillerce zengin yüksek düzlük hangisidir?', 'Teke Platosu', ['Haymana Platosu', 'Bozok Platosu', 'Ardahan Platosu'], 'Teke Platosu Batı Toroslar\'da Elmalı ve Korkuteli gibi karstik ovaları barındıran yüksek bir alandır.'),
  ('Dağların hemen eteğinde, akarsuların biriktirdiği yelpazelerin birleşmesiyle oluşan ovalara ne ad verilir?', 'Dağ eteği ovası', ['Delta ovası', 'Karstik ova', 'Tektonik çöküntü ovası'], 'Birikinti konileri yan yana gelip birleşince dağ eteği boyunca uzanan eğimli düzlükler oluşur.'),
  ('Bursa Ovası\'nın Uludağ\'ın kuzey eteğinde uzanmasının oluşum açısından anlamı nedir?', 'Fayla çöken bir alanda oluşması', ['Lav akıntılarının vadiyi kapatması', 'Buzulların oyduğu bir çanağın dolması', 'Bir lagünün kurumasıyla düzlük oluşması'], 'Uludağ ile Bursa Ovası arasında büyük bir fay bulunur; ova tektonik çöküntüde gelişmiştir.'),
  ('Platoların genellikle ovalardan daha az verimli tarım alanı sunmasının nedenlerinden biri aşağıdakilerden hangisidir?', 'İklimin daha sert olması', ['Platoların her zaman deniz kıyısında olması', 'Platoların alüvyonla örtülü olması', 'Platolarda hiç rüzgâr esmemesi'], 'Yükseklerde vejetasyon süresi kısalır, toprak genellikle incedir ve sulama zordur.'),
  ('A istasyonunda yıllık yağış 2.200 mm ve her ay yağış var; B istasyonunda yıllık yağış 350 mm ve en yağışlı mevsim ilkbahardır. A ve B için en uygun eşleştirme hangisidir?', 'A: Rize, B: Konya', ['A: Konya, B: Rize', 'A: Antalya, B: Erzurum', 'A: İzmir, B: Trabzon'], 'Bol ve düzenli yağış Doğu Karadeniz\'e, az ve ilkbahar maksimumlu yağış İç Anadolu\'ya özgüdür.'),
  ('Bir istasyonda ocak ortalaması 1 °C, temmuz ortalaması 23 °C, yıllık yağış 400 mm ve en yağışlı mevsim ilkbahardır. Bu istasyon büyük olasılıkla hangi bölgededir?', 'İç Anadolu', ['Doğu Karadeniz kıyısı', 'Akdeniz kıyısı', 'Marmara\'nın Karadeniz kıyısı'], 'Soğuk kış, sıcak yaz, az yağış ve ilkbahar yağış maksimumu İç Anadolu\'nun step iklimini gösterir.'),
  ('Kızılırmak gibi uzun bir akarsuyun ağzına yakın kesimdeki debisinin kaynağa yakın kesimdekinden çok daha büyük olmasının nedeni nedir?', 'Yol boyunca kolların katılması', ['Ağza doğru eğimin artması', 'Ağza yakın kesimde buharlaşmanın çok artması', 'Kaynakta yağışın ağız kesimine göre çok daha fazla olması'], 'Akarsu ilerledikçe havzası genişler ve yan kollar ile yeraltı suları ana yatağa katılır; bu nedenle debi ağza doğru artar.'),
  ('Bir dağcı Ağrı Dağı\'nın zirvesine çıkarken önce lav akıntıları, sonra kül katmanları ve en üstte kalıcı buzla karşılaşıyor. Bu gözlem dağın hangi iki özelliğini birlikte gösterir?', 'Volkanik ve çok yüksek oluşunu', ['Kıvrım dağı ve karstik olduğunu', 'Horst ve alçak olduğunu', 'Tortul kökenli ve buzulsuz olduğunu'], 'Lav ve kül katmanları volkanik kökeni, zirvedeki kalıcı buz ise yükseltinin kalıcı kar sınırını aştığını gösterir.'),
  ('Hakkâri Güneydoğu Anadolu\'ya komşu ve görece güneyde olmasına rağmen kışları çok sert ve karlı geçer. Bunun temel nedeni nedir?', 'Yükseltinin fazla olması', ['Karadeniz\'e yakın olması', 'Basra alçak basıncının kışın etkili olması', 'Akdeniz\'den gelen ılık havaya açık olması'], 'Hakkâri çevresi Cilo-Sat gibi çok yüksek dağlarla kaplıdır; yükselti enlemin ılıtıcı etkisini ortadan kaldırır.'),
  ('Bir gölün kıyısındaki eski kıyı çizgilerinin bugünkü su seviyesinden metrelerce yüksekte bulunması neyi gösterir?', 'Gölün küçüldüğünü', ['Gölün yakın zamanda oluştuğunu', 'Gölün bir lav setiyle yükseldiğini', 'Gölün denize bağlandığını'], 'Yüksekte kalmış kıyı izleri su seviyesinin zamanla düştüğünü, yani gölün küçüldüğünü kanıtlar.'),
  ('Bir kıyı bölgesinde kıyı oku, lagün ve geniş kumsalların bulunduğu biliniyor. Bu kıyı için en doğru çıkarım hangisidir?', 'Biriktirme süreçleri baskındır.', ['Kıyıda falez aşınımı egemendir.', 'Kıyı fiyort tipindedir.', 'Kıyıda buzul aşındırması etkilidir.'], 'Kıyı oku, lagün ve kumsal dalga ve akıntıların malzeme biriktirdiğini gösterir; aşınım kıyılarında falez ve platform baskındır.'),
  ('Bir sulak alanda su seviyesinin azaldığı, kıyıda tuz kabuğunun genişlediği ve kuş sayısının düştüğü gözleniyor. Bu sorunu azaltmak için en etkili önlem hangisidir?', 'Havzadaki su kullanımını sınırlamak', ['Sulak alanı kurutup tarla açmak', 'Göle akan dereleri başka yöne çevirmek', 'Kıyıya yeni kuyular açmak'], 'Sulak alanın sorunu gelen suyun azalmasıdır; havzada su tüketimini düzenlemek beslenmeyi artırır.'),
  ('Aynı gün öğle vaktinde boyları eşit iki çubuğun gölgesi ölçüldüğünde Samsun\'daki gölgenin Adana\'dakinden uzun olmasının nedeni nedir?', 'Işınların daha eğik gelmesi', ['Samsun\'un daha doğuda olması', 'Samsun\'da yerel saatin Adana\'dan daha ileri olması', 'Adana\'nın daha yüksekte olması'], 'Kuzeye gidildikçe güneş ışınlarının geliş açısı küçülür ve gölge boyu uzar.'),
  ('Eskişehir\'in Çifteler ilçesindeki Sakarbaşı kaynaklarından doğan akarsu hangisidir?', 'Sakarya', ['Porsuk Çayı', 'Kızılırmak', 'Gediz'], 'Sakarya Nehri Çifteler yakınındaki kaynaklardan çıkar ve Eskişehir-Ankara sınırı boyunca akar.'),
  ('Bir akarsuyun kaynağından ağzına kadar olan toplam alçalma miktarının uzunluğuna oranına ne ad verilir?', 'Ortalama eğim', ['Debi', 'Rejim', 'Akarsu havzası alanı'], 'Eğim, yükselti farkının yatay uzaklığa oranıdır; eğim büyüdükçe akarsuyun hızı ve aşındırma gücü artar.'),
  ('Kaynağı 2.000 m yükseltide olan ve 400 km akarak denize dökülen bir akarsuyun ortalama eğimi binde kaçtır?', 'Binde 5', ['Binde 2', 'Binde 20', 'Binde 50'], '2.000 m ÷ 400.000 m = 0,005 bulunur; bu da binde 5 eğim demektir.'),
  ('Bir gölün fazla suyunun çıkış yaptığı akarsuya ne ad verilir?', 'Gideğen', ['Ayak', 'Düden', 'Besleyici kol'], 'Gideğen gölden çıkan akarsudur; göle su getiren akarsulara ise besleyici akarsu denir.'),
  ('Akdeniz Bölgesi\'nde Toroslar\'ın kuzeyindeki Göller Yöresi\'nin kıyıya göre daha sert kışlar yaşamasının nedeni nedir?', 'Daha yüksekte ve dağların gerisinde olması', ['Daha güneyde olması', 'Karadeniz\'e kıyısı olması', 'Yazın kıyıya göre çok daha fazla yağış alması'], 'Göller Yöresi yaklaşık 900-1.200 m yükseltidedir ve Toroslar\'la denizden ayrılmıştır; bu nedenle karasal özellik gösterir.'),
  ('Türkiye\'de iklimin kısa mesafede değişmesine en iyi örnek aşağıdakilerden hangisidir?', 'Rize kıyısı ile Erzurum arasındaki fark', ['İzmir ile Manisa arasındaki benzerlik', 'Adana ile Mersin arasındaki benzerlik', 'Edirne ile Kırklareli arasındaki benzerlik'], 'Rize\'den Erzurum\'a kuş uçuşu kısa bir mesafede ılıman ve çok yağışlı iklimden sert karasal iklime geçilir.'),
  ('Doğu Anadolu\'da yüksek yaylalarda ağaç yerine çayırların yaygın olmasının en önemli nedeni nedir?', 'Uzun ve sert kışlar', ['Yaz kuraklığının çok uzun olması', 'Toprağın tuzlu olması', 'Deniz etkisinin güçlü olması'], 'Vejetasyon süresinin kısa olduğu, kışların uzun ve çok soğuk geçtiği yüksek alanlarda ağaçlar gelişemez; otlar ise kısa yazda büyür.'),
  ('Bir öğrenci Erzurum\'dan Trabzon\'a giderken yolun büyük kısmında yükseltinin azaldığını gözlemliyor. Hangi gözlem de bu yolculukta beklenir?', 'Bitki örtüsünün gürleşmesi', ['Havanın kuraklaşması', 'Kıyıya yaklaştıkça kışların sertleşmesi', 'Bitki örtüsünün steplere dönüşmesi'], 'Trabzon\'a yaklaşıldıkça deniz etkisi ve yağış artar; bitki örtüsü çayır ve kuru ormandan gür nemli ormanlara dönüşür.'),
  ('Van\'ın kuzeydoğusunda Bendimahi Çayı üzerinde, bazalt basamaklardan dökülen şelale hangisidir?', 'Muradiye Şelalesi', ['Tortum Şelalesi', 'Aşağı Düden Şelalesi', 'Kurşunlu Şelalesi'], 'Muradiye Şelalesi Bendimahi Çayı üzerinde, bazalt basamaklardan dökülür.'),
  ('Kahramanmaraş\'ın Elbistan ilçesi çevresinden doğan akarsu hangisidir?', 'Ceyhan', ['Seyhan', 'Göksu', 'Asi'], 'Ceyhan Nehri Elbistan yöresinden doğar ve Kahramanmaraş-Adana\'dan geçerek Akdeniz\'e dökülür.'),
  ('Aşağıdakilerden hangisi Karadeniz kıyılarında yağışın fazla olmasına doğrudan katkı yapmaz?', 'Kıyıda geniş delta ovalarının bulunması', ['Nemli hava kütlelerinin denizden gelmesi', 'Dağların kıyıya paralel uzanması', 'Kuzeyli rüzgârların dağ yamaçlarına çarpması'], 'Delta ovalarının varlığı yağışı artırmaz; yağışı deniz kaynaklı nem, rüzgâr yönü ve dağların yükseltici etkisi belirler.'),
  ('Göl ve sulak alanların korunması bölgenin iklimine nasıl katkı yapar?', 'Nem sağlayarak yerel iklimi yumuşatır.', ['Yağışı tamamen ortadan kaldırır.', 'Bölgeyi daha karasal yapar.', 'Rüzgâr hızını yıl boyunca sürekli artırır.'], 'Su yüzeyleri buharlaşmayla havaya nem katar ve sıcaklık farklarını azaltır.'),
  ('Türkiye\'nin kuzeybatısında, Bulgaristan sınırına yakın Istranca ormanlarının Marmara\'nın güneyindeki makilerden farklı olmasının temel nedeni nedir?', 'Karadeniz ikliminin etkisinde olması', ['Akdeniz ikliminin etkisinde olması', 'Sert karasal iklimin etkisinde olması', 'Bölgenin volkanik toprağa sahip olması'], 'Istranca\'nın Karadeniz\'e bakan yamaçları her mevsim yağış alır ve geniş yapraklı ormanlarla kaplıdır.'),
  ('Aşağıdaki iki yer arasında yıllık yağış farkının en fazla olması beklenen eşleştirme hangisidir?', 'Rize - Iğdır', ['İzmir - Manisa', 'Ankara - Kırşehir', 'Adana - Mersin'], 'Rize Türkiye\'nin en yağışlı, Iğdır ise en kurak yerlerinden biridir; diğer eşler birbirine yakın ve benzer iklimlidir.'),
  ('Aşağıdaki dağlardan hangisinde günümüzde kalıcı buzul bulunmaz?', 'Uludağ', ['Ağrı Dağı', 'Cilo Dağı', 'Kaçkar Dağı'], 'Uludağ\'da Kuaterner buzullaşmasının izleri bulunsa da günümüzde kalıcı buzul yoktur; Ağrı, Cilo ve Kaçkar\'da ise küçük de olsa buzullar vardır.'),
];
